banner_cookie_inferior.js:
(function(){
  var banner = document.getElementById('sl-cookie-banner');
  if(!banner) return;
  if(localStorage.getItem('sl_cookie_consent')) return;
  setTimeout(function(){ banner.classList.add('visible'); }, 800);
  function dismiss(val){
    localStorage.setItem('sl_cookie_consent', val);
    banner.classList.remove('visible');
    setTimeout(function(){ banner.remove(); }, 500);
  }
  var accept = document.getElementById('sl-cookie-accept');
  var decline = document.getElementById('sl-cookie-decline');
  if(accept) accept.addEventListener('click', function(){ dismiss('accepted'); });
  if(decline) decline.addEventListener('click', function(){ dismiss('declined'); });
})();

banner_topo_descartavel.js:
(function(){
  var banner = document.getElementById('sl-top-banner');
  var closeBtn = document.getElementById('sl-top-banner-close');
  if(!banner || !closeBtn) return;
  if(sessionStorage.getItem('sl_top_banner_closed')) { banner.classList.add('hidden'); return; }
  closeBtn.addEventListener('click', function(){
    banner.classList.add('hidden');
    sessionStorage.setItem('sl_top_banner_closed', '1');
  });
})();

modal_lgpd.js:
(function(){
  var modal;
  var key = 'sl_lgpd_prefs';
  if(localStorage.getItem(key)) return;
  function openModal(){
    if(typeof bootstrap !== 'undefined'){
      modal = new bootstrap.Modal(document.getElementById('sl-lgpd-modal'));
      modal.show();
    }
  }
  function save(analytics, marketing){
    localStorage.setItem(key, JSON.stringify({analytics:analytics, marketing:marketing, ts:Date.now()}));
    if(modal) modal.hide();
  }
  var saveBtn = document.getElementById('sl-lgpd-save');
  var rejectBtn = document.getElementById('sl-lgpd-reject');
  if(saveBtn) saveBtn.addEventListener('click', function(){
    save(
      document.getElementById('sl-analytics-toggle').checked,
      document.getElementById('sl-marketing-toggle').checked
    );
  });
  if(rejectBtn) rejectBtn.addEventListener('click', function(){ save(false, false); });
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', openModal);
  } else {
    openModal();
  }
})();
